// ==================== 数据加载和显示 ====================
function loadAndDisplay(retryCount = 0) {
    console.log(`📥 开始加载MVU数据... (尝试 ${retryCount + 1})`);

    try {
        return _loadAndDisplayInternal(retryCount);
    } catch (error) {
        console.error('❌ loadAndDisplay 执行出错:', error);
        console.error('错误堆栈:', error.stack);

        $('#village-status-top').html(`
            <div style="color: #ef4444; padding: 15px;">
                <p style="margin-bottom: 10px;">❌ 加载数据时发生错误</p>
                <p style="font-size: 12px; margin-bottom: 10px; color: #9ca3af;">${error.message}</p>
                <button onclick="loadVillageCardDisplay(0)" style="padding: 8px 16px; background: rgba(96, 165, 250, 0.2); border: 1px solid #60a5fa; border-radius: 5px; color: #60a5fa; cursor: pointer;">
                    🔄 重试
                </button>
            </div>
        `).removeClass('hidden');

        // 不要移除旧卡片，保留已有内容
        return;
    }
}

function _loadAndDisplayInternal(retryCount = 0) {
    const mvuAvailable = typeof Mvu !== 'undefined' ||
                        typeof window.Mvu !== 'undefined' ||
                        (window.parent && typeof window.parent.Mvu !== 'undefined');

    if (!mvuAvailable) {
        console.warn(`⚠️ MVU框架未加载，尝试次数: ${retryCount + 1}`);

        if (retryCount < 3) {
            $('#village-status-top').html(`
                <div style="color: #60a5fa;">
                    <p>⏳ 等待MVU框架加载中... (${retryCount + 1}/3)</p>
                    <button onclick="diagnoseMvuAvailability()" style="margin-top: 10px; padding: 8px 16px; background: rgba(96, 165, 250, 0.2); border: 1px solid #60a5fa; border-radius: 5px; color: #60a5fa; cursor: pointer;">
                        🔍 诊断MVU状态
                    </button>
                </div>
            `).removeClass('hidden');
            setTimeout(() => {
                loadAndDisplay(retryCount + 1);
            }, 2000);
        } else {
            $('#village-status-top').html(`
                <div style="color: #fbbf24;">
                    <p>⚠️ MVU框架未加载</p>
                    <p style="font-size: 12px; margin-top: 10px;">请先在聊天框运行相关初始化指令</p>
                    <div style="margin-top: 15px; display: flex; gap: 10px; justify-content: center; flex-wrap: wrap;">
                        <button onclick="diagnoseMvuAvailability()" style="padding: 8px 16px; background: rgba(96, 165, 250, 0.2); border: 1px solid #60a5fa; border-radius: 5px; color: #60a5fa; cursor: pointer;">
                            🔍 诊断
                        </button>
                        <button onclick="loadVillageCardDisplay(0)" style="padding: 8px 16px; background: rgba(96, 165, 250, 0.2); border: 1px solid #60a5fa; border-radius: 5px; color: #60a5fa; cursor: pointer;">
                            🔄 重试
                        </button>
                    </div>
                </div>
            `).removeClass('hidden');
            console.error('❌ MVU框架加载超时');
            diagnoseMvuAvailability();
        }
        return;
    }

    if (typeof Mvu === 'undefined' && window.parent && typeof window.parent.Mvu !== 'undefined') {
        window.Mvu = window.parent.Mvu;
        console.log('✅ 已从父窗口引用MVU');
    }

    console.log('✅ MVU框架已就绪');

    // 智能获取应该显示的数据
    let targetMessageId = 'latest';
    if (typeof getLastMessageId === 'function' && typeof getChatMessages === 'function') {
        let currentId = getLastMessageId();

        while (currentId >= 0) {
            const message = getChatMessages(currentId).at(-1);
            if (message && message.role !== 'user') {
                targetMessageId = currentId;
                if (currentId !== getLastMessageId()) {
                    console.log(`📝 向上查找到第 ${currentId} 层的AI消息`);
                }
                break;
            }
            currentId--;
        }

        if (currentId < 0) {
            targetMessageId = 'latest';
            console.warn('⚠️ 没有找到AI消息，使用最后一层');
        }
    }

    const data = Mvu.getMvuData({ type: 'message', message_id: targetMessageId });

    if (!data || !data.stat_data) {
        console.warn('⚠️ MVU数据为空，尝试自动修复...');

        if (retryCount === 0) {
            console.log('🔧 自动触发变量重新处理...');
            $('#village-status-top').html(`
                <div style="color: #60a5fa; padding: 15px;">
                    <p style="margin-bottom: 10px;">🔧 正在重新处理变量...</p>
                    <p style="font-size: 12px; color: #9ca3af;">首次加载时变量可能未处理完成</p>
                </div>
            `).removeClass('hidden');

            reprocessCurrentMessageVariables().then(() => {
                setTimeout(() => {
                    loadAndDisplay(1);
                }, 800);
            }).catch(err => {
                console.error('❌ 自动重新处理变量失败:', err);
                setTimeout(() => {
                    loadAndDisplay(2);
                }, 500);
            });

            return;
        }

        console.warn('⚠️ 自动修复后仍无法加载数据');
        $('#village-status-top').html(`
            <div style="color: #fbbf24; padding: 15px;">
                <p style="margin-bottom: 10px;">⚠️ 无法加载数据</p>
                <p style="font-size: 12px; margin-bottom: 15px;">可能需要先发送消息生成数据</p>
                <div style="margin-top: 15px; display: flex; gap: 10px; justify-content: center;">
                    <button onclick="loadVillageCardDisplay(0)" style="padding: 8px 16px; background: rgba(96, 165, 250, 0.2); border: 1px solid #60a5fa; border-radius: 5px; color: #60a5fa; cursor: pointer;">
                        🔄 重试加载
                    </button>
                    <button onclick="diagnoseMvuAvailability()" style="padding: 8px 16px; background: rgba(96, 165, 250, 0.2); border: 1px solid #60a5fa; border-radius: 5px; color: #60a5fa; cursor: pointer;">
                        🔍 诊断
                    </button>
                </div>
            </div>
        `).removeClass('hidden');

        // 不要移除旧卡片，保留已有内容
        return;
    }

    const statData = data.stat_data;
    console.log('📊 stat_data字段:', Object.keys(statData));

    // 隐藏顶部加载提示
    $('#village-status-top').addClass('hidden');

    // 生成卡片HTML
    const cardHtml = generateVillageCard(statData);

    // 只有在成功生成新卡片后才移除旧卡片
    $('.village-card-wrapper').remove();

    // 在顶部状态区域后追加新卡片
    $('#village-card-status').append(cardHtml);

    // 初始化样式和功能
    initializeCardStyles();
    setupEventDelegation();

    // 延迟初始化拖拽功能
    setTimeout(() => {
        const $container = window.top ? $(window.top.document).find('#village-card-status') : $('#village-card-status');
        const container = $container[0];

        if (!container) {
            console.error('❌ 容器不存在，无法初始化拖拽');
        } else if (container.dataset.dragInitialized !== 'true') {
            try {
                initializeDragFeature();
                container.dataset.dragInitialized = 'true';
                console.log('✅ 拖拽功能已启用');
            } catch (error) {
                console.error('❌ 拖拽初始化失败:', error);
            }
        }
    }, 300);

    console.log('✅ 数据显示完成');
}

// ========== 生成城中村卡片 ==========
function generateVillageCard(statData) {
    // 需要从原城中村文件引入生成器函数
    // 这里先占位，后续会补充完整的生成器

    const generators = {
        worldInfo: generateWorldInfo,
        building: generateBuilding,
        tenants: generateTenants,
        characterBonds: generateCharacterBonds,
        map: generateMap,
        plot: generatePlot
    };

    // 生成Tab标签
    let tabsHtml = '';
    let panelsHtml = '';
    let firstTab = true;

    Object.entries(VILLAGE_CONFIG.fields).forEach(([key, config]) => {
        const dataFieldName = config.name;
        const icon = config.icon || '📋';
        const generator = generators[key];

        if (!generator) {
            console.warn(`⚠️ 没有找到"${key}"的生成器`);
            return;
        }

        const fieldData = statData[dataFieldName];
        if (!fieldData) {
            console.warn(`⚠️ 没有找到"${dataFieldName}"数据`);
            return;
        }

        // 生成Tab标签
        tabsHtml += `
            <div class="village-tab ${firstTab ? 'active' : ''}" data-tab="${key}">
                <span>${icon}</span>
                <span>${dataFieldName}</span>
            </div>
        `;

        // 生成Tab内容
        let panelContent;
        try {
            panelContent = generator(fieldData);
        } catch (error) {
            console.error(`❌ 生成"${dataFieldName}"面板时出错:`, error);
            panelContent = `
                <div class="section">
                    <div class="section-title" style="color: #ef4444;">⚠️ ${dataFieldName}</div>
                    <div class="section-content">
                        <div style="padding: 20px; text-align: center; color: #9ca3af;">
                            <p>生成面板时出错</p>
                            <p style="font-size: 12px; margin-top: 10px; color: #ef4444;">${error.message}</p>
                        </div>
                    </div>
                </div>
            `;
        }

        panelsHtml += `
            <div class="village-panel-wrapper ${firstTab ? 'active' : ''}" data-tab="${key}">
                ${panelContent}
            </div>
        `;

        firstTab = false;
    });

    return `
    <div class="village-card-wrapper" id="village-main-card">
        <div class="village-card-3d">
            <div class="village-card-main">
                <div class="village-card-content-inner">
                    <!-- 控制按钮 -->
                    <div class="village-card-control-buttons">
                        <div class="village-card-control-left">
                            <button class="village-card-collapse-btn" data-action="toggle-collapse" title="收起/展开">
                                <span>📌</span>
                            </button>
                        </div>
                        <div class="village-card-control-right">
                            <button class="village-card-style-btn" data-action="toggle-style" title="切换样式">
                                <span>🎨</span>
                            </button>
                            <button class="village-card-refresh-btn" data-action="refresh" title="刷新数据">
                                <span class="icon">🔄</span>
                            </button>
                        </div>
                    </div>

                    <!-- Tab标签栏 -->
                    <div class="village-tabs">
                        ${tabsHtml}
                    </div>

                    <!-- Tab内容区域 -->
                    <div class="village-tab-content">
                        ${panelsHtml}
                    </div>
                </div>
            </div>
        </div>
    </div>
    `;
}

// ==================== 辅助函数 ====================
function safeGetArray(data, defaultValue = []) {
    try {
        if (Array.isArray(data)) {
            return data.filter(item => item !== '$__META_EXTENSIBLE__$');
        } else if (data && typeof data === 'string') {
            return [data];
        } else if (data === null || data === undefined) {
            return defaultValue;
        } else {
            console.warn('⚠️ 数据不是数组，尝试转换:', data);
            return defaultValue;
        }
    } catch (e) {
        console.warn('⚠️ 处理数组数据时出错:', e);
        return defaultValue;
    }
}

