    const monthIncome = worldInfo.财务状况?.本月收入?.[0] || 0;
    const unpaidRent = worldInfo.财务状况?.待收租金?.[0] || 0;
    const repairCost = worldInfo.财务状况?.维修支出?.[0] || 0;

    return `
