                <div class="world-item">
                    <span class="world-label">☁️ 室外</span>
                    <span class="world-value">${outdoorTemp}°C</span>
                </div>
                <div class="world-item">
                    <span class="world-label">🌦️ 天气</span>
                    <span class="world-value">${weather}</span>
