    const buildYear = building.基础信息?.建造年份?.[0] || 2008;
    const floors = building.基础信息?.楼层数?.[0] || 3;
    const totalArea = building.基础信息?.总面积?.[0] || 0;
    const totalRooms = building.基础信息?.房间总数?.[0] || 0;
