    const vacant = building.基础信息?.空置数?.[0] || 0;

    const stairStatus = building.公共设施状况?.楼梯?.[0] || '';
    const waterStatus = building.公共设施状况?.供水系统?.[0] || '';
    const powerStatus = building.公共设施状况?.供电系统?.[0] || '';
    const roofStatus = building.公共设施状况?.天台?.[0] || '';

    const repairs = safeGetArray(building.待维修项目?.[0]);

    return `
