                    <div class="building-value">${floors}层</div>
                </div>
                <div class="building-item">
                    <div class="building-label">总面积</div>
                    <div class="building-value">${totalArea}㎡</div>
                </div>
                <div class="building-item">
                    <div class="building-label">总房间</div>
                    <div class="building-value">${totalRooms}间</div>
                </div>
                <div class="building-item">
                    <div class="building-label">已出租</div>
                    <div class="building-value">${occupied}间</div>
                </div>
                <div class="building-item">
                    <div class="building-label">空置</div>
                    <div class="building-value">${vacant}间</div>
                </div>
            </div>

            ${stairStatus || waterStatus || powerStatus || roofStatus ? `
            <div style="margin-top: 10px;">
                <div class="status-label" style="margin-bottom: 5px;">设施状况</div>
                ${stairStatus ? `<div class="status-row"><span class="status-label">🪜 楼梯</span><span class="status-value">${stairStatus}</span></div>` : ''}
                ${waterStatus ? `<div class="status-row"><span class="status-label">💧 供水</span><span class="status-value">${waterStatus}</span></div>` : ''}
                ${powerStatus ? `<div class="status-row"><span class="status-label">⚡ 供电</span><span class="status-value">${powerStatus}</span></div>` : ''}
                ${roofStatus ? `<div class="status-row"><span class="status-label">🏠 天台</span><span class="status-value">${roofStatus}</span></div>` : ''}
            </div>
            ` : ''}

            ${repairs.length > 0 ? `
