                <div class="status-label" style="margin-bottom: 5px;">待维修项目 (${repairs.length})</div>
                ${repairs.map(r => `<div class="status-row"><span>🔧 ${r}</span></div>`).join('')}
            </div>
            ` : ''}
        </div>
    </div>
    `;
}

