                            ${moveInTime ? `<div><span style="color: #9ca3af;">入住:</span> ${moveInTime}</div>` : ''}
                            ${rentPeriod ? `<div><span style="color: #9ca3af;">租期:</span> ${rentPeriod}</div>` : ''}
