        const breastShape = bodyFeatures.乳房?.形状?.[0] || '-';
        const nippleColor = bodyFeatures.乳房?.乳头颜色?.[0] || '-';
        const privateType = bodyFeatures.私处?.类型?.[0] || '-';

        // 性经验
        const sexExp = beauty.性经验 || {};
