                    ${bottom !== '未知' ? `<div style="font-size: 11px;"><span style="color: #9ca3af;">下装:</span> ${bottom}</div>` : ''}
                    ${underwear !== '未知' ? `<div style="font-size: 11px;"><span style="color: #9ca3af;">内衣:</span> ${underwear}</div>` : ''}
                    ${panties !== '未知' ? `<div style="font-size: 11px;"><span style="color: #9ca3af;">内裤:</span> ${panties}</div>` : ''}
                    ${stockings !== '无' ? `<div style="font-size: 11px;"><span style="color: #9ca3af;">丝袜:</span> ${stockings}</div>` : ''}
                    ${shoes !== '未知' ? `<div style="font-size: 11px;"><span style="color: #9ca3af;">鞋子:</span> ${shoes}</div>` : ''}
                </div>
            </div>

            <!-- 身体特征 -->
            <div style="margin-top: 10px;">
                <div style="color: rgba(255, 255, 255, 0.5); font-size: 11px; margin-bottom: 6px;">身体特征</div>
                <div class="bond-stats">
                    <div><span style="color: #9ca3af;">三围:</span> ${bust}/${waist}/${hips}</div>
