                    ${nippleColor !== '-' ? `<div style="font-size: 11px;"><span style="color: #9ca3af;">乳头颜色:</span> ${nippleColor}</div>` : ''}
                    ${privateType !== '-' ? `<div style="font-size: 11px;"><span style="color: #9ca3af;">私处类型:</span> ${privateType}</div>` : ''}
                </div>
