                    <div><span style="color: #9ca3af;">性行为:</span> ${sexCount}次</div>
                    <div><span style="color: #9ca3af;">肛交:</span> ${analExp}</div>
                    <div><span style="color: #9ca3af;">口交:</span> ${oralExp}</div>
                    <div><span style="color: #9ca3af;">性伴侣:</span> ${partnerCount}人</div>
                    ${firstPartner !== '-' ? `<div style="font-size: 11px;"><span style="color: #9ca3af;">初次对象:</span> ${firstPartner}</div>` : ''}
