                    <div style="font-size: 11px;"><span style="color: #9ca3af;">阴蒂状态:</span> ${clitState}</div>
                    ${uterusState !== '-' ? `<div style="font-size: 11px;"><span style="color: #9ca3af;">子宫状态:</span> ${uterusState}</div>` : ''}
                    ${menstrualCycle !== '-' ? `<div style="font-size: 11px;"><span style="color: #9ca3af;">月经周期:</span> ${menstrualCycle}</div>` : ''}
                    ${pregnancy !== '-' ? `<div style="font-size: 11px;"><span style="color: #9ca3af;">怀孕状态:</span> ${pregnancy}</div>` : ''}
