// ========== 生成地图系统 ==========
function generateMap(map) {
    const buildingName = map.当前楼房?.楼房名称?.[0] || '未知';
    const buildingDesc = map.当前楼房?.楼房描述?.[0] || '';

    let floorsHtml = '';
    if (map.楼层信息) {
        const floors = Object.keys(map.楼层信息).filter(k => k !== '$meta');
        if (floors.length > 0) {
            floorsHtml = floors.map(floorName => {
                const floor = map.楼层信息[floorName];
                const rooms = safeGetArray(floor.房间列表?.[0]);
                const desc = floor.描述?.[0] || '';
                const status = floor.状态?.[0] || '';

                return `
                <div class="map-location">
                    <div class="location-name">${floorName}</div>
                    ${status ? `<div style="color: #4ade80; font-size: 10px;">(${status})</div>` : ''}
                    ${desc ? `<div style="font-size: 10px; color: #9ca3af; margin-top: 2px;">${desc}</div>` : ''}
                    ${rooms.length > 0 ? `<div style="font-size: 10px; margin-top: 2px;">房间: ${rooms.join(', ')}</div>` : ''}
                </div>
                `;
            }).join('');
        }
    }

    let envHtml = '';
    if (map.周边环境) {
        const places = Object.keys(map.周边环境).filter(k => k !== '$meta');
        if (places.length > 0) {
            envHtml = places.map(placeName => {
                const place = map.周边环境[placeName];
                const distance = place.距离?.[0] || 0;
                const desc = place.描述?.[0] || '';

                return `
                <div class="map-location">
                    <div class="location-name">${placeName}</div>
                    <div style="font-size: 10px;">${distance}米</div>
                    ${desc ? `<div style="font-size: 10px; color: #9ca3af; margin-top: 2px;">${desc}</div>` : ''}
                </div>
                `;
            }).join('');
        }
    }

    return `
    <div class="section">
        <div class="section-title">🗺️ 地图系统</div>
        <div class="section-content">
            <div style="margin-bottom: 10px;">
                <div class="status-label">当前楼房</div>
                <div class="status-value">${buildingName}</div>
                ${buildingDesc ? `<div style="font-size: 12px; color: #9ca3af; margin-top: 4px;">${buildingDesc}</div>` : ''}
            </div>

            ${floorsHtml ? `
            <div style="margin-top: 10px;">
                <div class="status-label" style="margin-bottom: 5px;">楼层信息</div>
                <div class="map-grid">
                    ${floorsHtml}
                </div>
            </div>
            ` : ''}

            ${envHtml ? `
            <div style="margin-top: 10px;">
                <div class="status-label" style="margin-bottom: 5px;">周边环境</div>
                <div class="map-grid">
                    ${envHtml}
                </div>
            </div>
            ` : ''}
        </div>
    </div>
    `;
}

