function loadAndDisplay(retryCount = 0) {
    console.log(`📥 开始加载MVU数据... (尝试 ${retryCount + 1})`);

    try {
        return _loadAndDisplayInternal(retryCount);
    } catch (error) {
        console.error('❌ loadAndDisplay 执行出错:', error);
        console.error('错误堆栈:', error.stack);

        $('#village-status-top').html(`
