                    <div class="building-value">${totalArea}㎡</div>
                </div>
                <div class="building-item">
                    <div class="building-label">总房间</div>
                    <div class="building-value">${totalRooms}间</div>
                </div>
                <div class="building-item">
                    <div class="building-label">已出租</div>
                    <div class="building-value">${occupied}间</div>
                </div>
                <div class="building-item">
                    <div class="building-label">空置</div>
                    <div class="building-value">${vacant}间</div>
