                                items.push(`<div style="font-size: 11px; padding: 4px 8px; background: rgba(255, 255, 255, 0.05); border-radius: 4px;"><span style="color: #9ca3af;">👋 第一次见面:</span> ${meetings.join('; ')}</div>`);
                            }
                        }
                        if (records.第一次收租?.[0]) {
                            const rents = safeGetArray(records.第一次收租[0]);
                            if (rents.length > 0) {
                                items.push(`<div style="font-size: 11px; padding: 4px 8px; background: rgba(255, 255, 255, 0.05); border-radius: 4px;"><span style="color: #9ca3af;">💰 第一次收租:</span> ${rents.join('; ')}</div>`);
                            }
                        }
                        if (records.印象深刻的事?.[0]) {
                            const events = safeGetArray(records.印象深刻的事[0]);
                            if (events.length > 0) {
                                items.push(`<div style="font-size: 11px; padding: 4px 8px; background: rgba(255, 255, 255, 0.05); border-radius: 4px;"><span style="color: #9ca3af;">⭐ 印象深刻:</span> ${events.join('; ')}</div>`);
                            }
                        }
                        if (records.关系变化?.[0]) {
                            const changes = safeGetArray(records.关系变化[0]);
                            if (changes.length > 0) {
                                items.push(`<div style="font-size: 11px; padding: 4px 8px; background: rgba(255, 255, 255, 0.05); border-radius: 4px;"><span style="color: #9ca3af;">💕 关系变化:</span> ${changes.join('; ')}</div>`);
                            }
                        }

                        return items.length > 0 ? items.join('') : '<div style="font-size: 11px; color: #6b7280;">暂无记录</div>';
                    })()}
                </div>
            </div>
            ` : ''}
        </div>
        `;
    }).join('');

    return `
    <div class="section">
        <div class="section-title">💖 人物羁绊 (${characters.length}人)</div>
        <div class="section-content">
            <div class="bond-list">
                ${charactersHtml}
            </div>
        </div>
    </div>
    `;
}

// ========== 生成地图系统 ==========
function generateMap(map) {
    const buildingName = map.当前楼房?.楼房名称?.[0] || '未知';
    const buildingDesc = map.当前楼房?.楼房描述?.[0] || '';

    let floorsHtml = '';
    if (map.楼层信息) {
        const floors = Object.keys(map.楼层信息).filter(k => k !== '$meta');
        if (floors.length > 0) {
            floorsHtml = floors.map(floorName => {
                const floor = map.楼层信息[floorName];
                const rooms = safeGetArray(floor.房间列表?.[0]);
                const desc = floor.描述?.[0] || '';
                const status = floor.状态?.[0] || '';

                return `
                <div class="map-location">
                    <div class="location-name">${floorName}</div>
                    ${status ? `<div style="color: #4ade80; font-size: 10px;">(${status})</div>` : ''}
                    ${desc ? `<div style="font-size: 10px; color: #9ca3af; margin-top: 2px;">${desc}</div>` : ''}
                    ${rooms.length > 0 ? `<div style="font-size: 10px; margin-top: 2px;">房间: ${rooms.join(', ')}</div>` : ''}
                </div>
                `;
            }).join('');
        }
    }

    let envHtml = '';
    if (map.周边环境) {
        const places = Object.keys(map.周边环境).filter(k => k !== '$meta');
        if (places.length > 0) {
            envHtml = places.map(placeName => {
                const place = map.周边环境[placeName];
                const distance = place.距离?.[0] || 0;
                const desc = place.描述?.[0] || '';

                return `
                <div class="map-location">
                    <div class="location-name">${placeName}</div>
                    <div style="font-size: 10px;">${distance}米</div>
                    ${desc ? `<div style="font-size: 10px; color: #9ca3af; margin-top: 2px;">${desc}</div>` : ''}
                </div>
                `;
            }).join('');
        }
    }

    return `
    <div class="section">
        <div class="section-title">🗺️ 地图系统</div>
        <div class="section-content">
            <div style="margin-bottom: 10px;">
                <div class="status-label">当前楼房</div>
                <div class="status-value">${buildingName}</div>
                ${buildingDesc ? `<div style="font-size: 12px; color: #9ca3af; margin-top: 4px;">${buildingDesc}</div>` : ''}
            </div>

            ${floorsHtml ? `
            <div style="margin-top: 10px;">
                <div class="status-label" style="margin-bottom: 5px;">楼层信息</div>
                <div class="map-grid">
                    ${floorsHtml}
                </div>
            </div>
            ` : ''}

            ${envHtml ? `
            <div style="margin-top: 10px;">
                <div class="status-label" style="margin-bottom: 5px;">周边环境</div>
                <div class="map-grid">
                    ${envHtml}
                </div>
            </div>
            ` : ''}
        </div>
    </div>
    `;
}

// ========== 生成剧情系统 ==========
function generatePlot(plot) {
    const events = safeGetArray(plot.重大事件?.[0]);
    const achievements = safeGetArray(plot.成就列表?.[0]);
    const tags = safeGetArray(plot.剧情标签?.[0]);

    return `
    <div class="section">
        <div class="section-title">📖 剧情系统</div>
        <div class="section-content">
            ${events.length > 0 ? `
            <div style="margin-bottom: 10px;">
                <div class="status-label" style="margin-bottom: 5px;">重大事件 (${events.length})</div>
                <div class="plot-list">
                    ${events.map(e => `
                    <div class="plot-item">
                        <div class="plot-description">${e}</div>
                    </div>
                    `).join('')}
                </div>
            </div>
            ` : ''}

            ${achievements.length > 0 ? `
            <div style="margin-bottom: 10px;">
                <div class="status-label" style="margin-bottom: 5px;">成就列表 (${achievements.length})</div>
                <div class="plot-list">
                    ${achievements.map(a => `
                    <div class="plot-item">
                        <div class="plot-description">🏆 ${a}</div>
                    </div>
                    `).join('')}
                </div>
            </div>
            ` : ''}

            ${tags.length > 0 ? `
            <div>
                <div class="status-label">剧情标签</div>
                <div class="status-value">${tags.join(', ')}</div>
            </div>
            ` : ''}

            ${events.length === 0 && achievements.length === 0 && tags.length === 0 ? `
            <div style="padding: 20px; text-align: center; color: #9ca3af;">
                暂无剧情记录
            </div>
            ` : ''}
        </div>
    </div>
    `;
}

// ========== 样式切换功能 ==========
let currentCardStyle = 1;
function toggleCardStyle() {
    currentCardStyle = currentCardStyle === 1 ? 2 : 1;
    const $container = window.top ? $(window.top.document).find('#village-card-status') : $('#village-card-status');
    $container.attr('data-style', `style${currentCardStyle}`);
    console.log(`✨ 切换到样式${currentCardStyle}`);
}

// ========== 初始化卡片样式 ==========
function initializeCardStyles() {
    const $container = window.top ? $(window.top.document).find('#village-card-status') : $('#village-card-status');
    $container.attr('data-style', 'style1');
    console.log('✅ 卡片样式初始化为 style1');
}

// ========== 设置事件委托 ==========
function setupEventDelegation() {
    const $container = window.top ? $(window.top.document).find('#village-card-status') : $('#village-card-status');

    // 移除旧的事件绑定
    $container.off('click');

    // 使用事件委托绑定所有按钮点击事件
    $container.on('click', '[data-action]', async function(e) {
        e.preventDefault();
        e.stopPropagation();

        const $btn = $(this);
        const action = $btn.data('action');

        console.log('🔔 按钮被点击:', action);

        if ($btn.prop('disabled')) {
            console.warn('⚠️ 按钮已禁用，忽略点击');
            return;
        }

        try {
            switch(action) {
                case 'toggle-style':
                    console.log('🎨 切换样式...');
                    toggleCardStyle();
                    break;

                case 'refresh':
                    console.log('🔄 开始刷新数据...');
                    $btn.addClass('refreshing').prop('disabled', true);

                    try {
                        console.log('🔧 触发重新处理变量...');
                        await reprocessCurrentMessageVariables();

                        console.log('⏳ 等待变量处理完成...');
                        await new Promise(resolve => setTimeout(resolve, 500));

                        console.log('🔄 刷新显示数据...');
                        // 不要先清除，让loadAndDisplay内部处理替换
                        loadAndDisplay();

                        console.log('✅ 刷新完成');
                    } finally {
                        setTimeout(() => {
                            $btn.removeClass('refreshing').prop('disabled', false);
                        }, 500);
                    }
                    break;

                case 'toggle-collapse':
                    console.log('📌 切换收起状态');
                    const $cardWrapper = $('.village-card-wrapper');
                    $cardWrapper.toggleClass('collapsed');

                    const isCollapsed = $cardWrapper.hasClass('collapsed');
                    $btn.find('span').text(isCollapsed ? '📍' : '📌');
                    $btn.attr('title', isCollapsed ? '展开' : '收起');
                    break;

                default:
                    console.warn('⚠️ 未知的操作:', action);
            }
        } catch (error) {
            console.error('❌ 操作失败:', error);
            if (typeof toastr !== 'undefined') {
                toastr.error('操作失败：' + error.message);
            }
        }
    });

    // Tab切换事件
    $container.on('click', '.village-tab', function(e) {
        e.preventDefault();
        e.stopPropagation();

        const $tab = $(this);
        const tabKey = $tab.data('tab');

        console.log('📑 切换到Tab:', tabKey);

        // 切换Tab激活状态
        $('.village-tab').removeClass('active');
        $tab.addClass('active');

        // 切换面板显示
        $('.village-panel-wrapper').removeClass('active');
        $(`.village-panel-wrapper[data-tab="${tabKey}"]`).addClass('active');
    });

    console.log('✅ 事件委托已设置');
}

// ========== 重新处理当前消息变量 ==========
async function reprocessCurrentMessageVariables() {
    try {
        if (typeof getLastMessageId !== 'function' || typeof getChatMessages !== 'function') {
            console.warn('⚠️ 必要函数不可用');
            return;
        }

        let messageId = getLastMessageId();

        if (messageId < 0) {
            console.warn('⚠️ 没有有效的消息ID');
            return;
        }

        let foundAiMessage = false;
        while (messageId >= 0) {
            const message = getChatMessages(messageId).at(-1);
            if (message && message.role !== 'user') {
                foundAiMessage = true;
                if (messageId !== getLastMessageId()) {
                    console.log(`📝 向上查找到第 ${messageId} 层的AI消息，重新处理该层`);
                }
                break;
            }
            messageId--;
        }

        if (!foundAiMessage || messageId < 0) {
            console.warn('⚠️ 没有找到AI消息，无法重新处理变量');
            return;
        }

        console.log(`🔧 重新处理消息 ${messageId} 的变量...`);

        if (typeof window.parent?.handleVariablesInMessage === 'function') {
            await window.parent.handleVariablesInMessage(messageId);
            console.log('✅ 变量重新处理完成 (方法1)');
            return;
        }

        if (typeof updateVariablesWith === 'function') {
            await updateVariablesWith(vars => {
                _.unset(vars, 'stat_data');
                _.unset(vars, 'delta_data');
                _.unset(vars, 'display_data');
                _.unset(vars, 'schema');
                return vars;
            }, { type: 'message', message_id: messageId });

            if (typeof window.parent?.handleVariablesInMessage === 'function') {
                await window.parent.handleVariablesInMessage(messageId);
            }
            console.log('✅ 变量重新处理完成 (方法2)');
            return;
        }

        console.warn('⚠️ 没有找到可用的变量处理函数');

    } catch (error) {
        console.error('❌ 重新处理变量时出错:', error);
    }
}

// ==================== 事件监听和脚本启动 ====================
function handleVillageMessageReceived() {
    console.log('📨 收到 MESSAGE_RECEIVED 事件，刷新状态栏数据...');
    setTimeout(() => {
        try {
            const $container = window.top ? $(window.top.document).find('#village-card-status') : $('#village-card-status');
            if ($container.length > 0) {
                // 不要先清除，让loadAndDisplay内部处理替换
                loadAndDisplay();
            } else {
                console.warn('⚠️ 状态栏未初始化，跳过数据更新');
            }
        } catch (error) {
            console.error('❌ 刷新状态栏时出错:', error);
        }
    }, 500);
}

$(() => {
    console.log('📄 DOM已就绪，检测MVU框架...');

    waitForMvu(() => {
        console.log('🚀 开始初始化城中村卡片状态栏');
        initializeVillageCardStatus();

        if (typeof eventSource !== 'undefined' && eventSource.on) {
            eventSource.on('MESSAGE_RECEIVED', handleVillageMessageReceived);
            console.log('✅ 已注册 MESSAGE_RECEIVED 事件监听 (eventSource)');
        } else if (typeof eventOn === 'function' && typeof tavern_events !== 'undefined' && tavern_events.MESSAGE_RECEIVED) {
            eventOn(tavern_events.MESSAGE_RECEIVED, handleVillageMessageReceived);
            console.log('✅ 已注册 MESSAGE_RECEIVED 事件监听 (tavern_events)');
        } else {
            console.warn('⚠️ 无法注册 MESSAGE_RECEIVED 事件（事件系统未找到）');
        }
    });
});

$(window).on('unload', () => {
    if (typeof eventSource !== 'undefined' && eventSource.removeListener) {
        eventSource.removeListener('MESSAGE_RECEIVED', handleVillageMessageReceived);
        console.log('🗑️ 已移除 MESSAGE_RECEIVED 事件监听');
    } else if (typeof eventRemoveListener === 'function' && typeof tavern_events !== 'undefined' && tavern_events.MESSAGE_RECEIVED) {
        eventRemoveListener(tavern_events.MESSAGE_RECEIVED, handleVillageMessageReceived);
        console.log('🗑️ 已移除 MESSAGE_RECEIVED 事件监听');
    }

    cleanupVillageCardStatus();
});

console.log('📦 城中村卡片状态栏脚本已加载完成');

